    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }
    }

    private static class FastOutput {
        private final OutputStream out = System.out;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;

        void writeInt(int value) throws IOException {
            if (value >= 10) writeInt(value / 10);
            writeByte((byte) ('0' + value % 10));
        }

        void writeByte(byte b) throws IOException {
            if (ptr == buffer.length) flush();
            buffer[ptr++] = b;
        }

        void flush() throws IOException {
            out.write(buffer, 0, ptr);
            ptr = 0;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();
        int p = fs.nextInt();

        int[] rows = new int[n];
        int[] cols = new int[m];
        for (int i = 0; i < n; i++) rows[i] = i + 1;
        for (int j = 0; j < m; j++) cols[j] = j + 1;

        for (int k = 0; k < p; k++) {
            char operation = fs.next().charAt(0);
            int a = fs.nextInt();
            int b = fs.nextInt();

            if (operation == 'L') {
                int temp = rows[a - 1];
                rows[a - 1] = rows[b - 1];
                rows[b - 1] = temp;
            } else {
                int temp = cols[a - 1];
                cols[a - 1] = cols[b - 1];
                cols[b - 1] = temp;
            }
        }

        FastOutput out = new FastOutput();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (j > 0) out.writeByte((byte) ' ');
                out.writeInt((rows[i] - 1) * m + cols[j]);
            }
            out.writeByte((byte) '\n');
        }
        out.flush();
    }
}
